interface.definition:
a!localVariables(
  local!statusFilter,
  local!typeFilter,
  local!regionFilter,
  local!positionFilter,
  local!subPositionFilter,
  local!yearFilter,
  local!nameFilter,
  local!originatingBuFilter,
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!paging: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
  ),
  local!pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: - 1,
    sort: {
      #"SYSTEM_SYSRULES_sortInfo"(field: "subPositionId", ascending: true)
    }
  ),
  local!bu: union(
    property(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
        returnCDT: true,
        regionId: { 23, 24 },
        columns: { "bu" },
        isActive: true
      ),
      "bu",
      tostring(null)
    ),
    property(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
        returnCDT: true,
        regionId: { 406 },
        columns: { "bu" },
        isActive: true
      ),
      "bu",
      tostring(null)
    )
  ),
  local!rotationalSubPositionId: tointeger(
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11636843"
  ),
  local!subPositionDropDown: a!refreshVariable(
    value: if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!positionFilter),
      null,
      #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3595917"(
        returnCDT: true,
        subPositionIds: if(
          length(split(local!positionFilter, "; ")) = 2,
          append(
            local!rotationalSubPositionId,
            #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11685968"
          ),
          if(
            contains(
              tointeger(local!positionFilter),
              #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
            ),
            local!rotationalSubPositionId,
            null
          )
        ),
        refId: local!positionFilter,
        columns: { "refId", "subPositionId", "subPosition" },
        pagingInfo: local!pagingInfo
      )
    ),
    refreshOnVarChange: local!positionFilter
  ),
  local!nominationData: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3851730"(
    fetchTotalCount: true,
    columns: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934123",
    pagingInfo: local!paging,
    fullName: if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!nameFilter),
      null,
      local!nameFilter
    ),
    nominationStatus: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!statusFilter),
      null,
      local!statusFilter
    ),
    nominationTypeId: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!typeFilter),
      null,
      local!typeFilter
    ),
    region: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!regionFilter),
      null,
      local!regionFilter
    ),
    positionTypeId: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!positionFilter),
      null,
      local!positionFilter
    ),
    originatingBU: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!userBU),
      local!originatingBuFilter,
      local!userBU,

    ),
    returnBu: local!userBU,
    subPositionTypeId: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!subPositionFilter),
      null,
      local!subPositionFilter
    ),
    fiscalYear: if(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!yearFilter),
      null,
      local!yearFilter
    )
  ),
  local!documentId,
  local!isError: false,
  local!fYearDropDown: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
  local!exportType,
  {
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "refresh",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!statusFilter,
                      local!typeFilter,
                      local!regionFilter,
                      local!positionFilter,
                      local!subPositionFilter,
                      local!yearFilter,
                      local!nameFilter,
                      local!originatingBuFilter
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              ),
              linkStyle: "STANDALONE"
            ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: " Clear Filters",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!statusFilter,
                      local!typeFilter,
                      local!regionFilter,
                      local!positionFilter,
                      local!subPositionFilter,
                      local!yearFilter,
                      local!nameFilter,
                      local!originatingBuFilter,
                      local!documentId
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              ),
              linkStyle: "STANDALONE",
              style: "STRONG"
            )
          },
          align: "RIGHT"
        ),
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5160288"(
          statusFilter: local!statusFilter,
          nominationTypeFilter: local!typeFilter,
          nameFilter: local!nameFilter,
          paging: local!paging,
          regionFilter: local!regionFilter,
          originatingBuFilter: local!originatingBuFilter,
          positionFilter: local!positionFilter,
          subPositionFilter: local!subPositionFilter,
          originatingBuDropDown: local!bu,
          subPositionDropDown: local!subPositionDropDown,
          yearFilter: local!yearFilter,
          documentId: local!documentId,
          fYearDropDown: local!fYearDropDown,
          userBu: local!userBU
        )
      },
      style: "ACCENT",
      marginBelow: "STANDARD",
      showBorder: false
    ),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_ButtonLayout"(
              secondaryButtons: {
                #"SYSTEM_SYSRULES_ButtonWidget"(
                  label: "Go Back",
                  value: ri!chooseId,
                  saveInto: {
                    a!save(ri!chooseId, 1),
                    a!save(
                      {
                        local!statusFilter,
                        local!typeFilter,
                        local!regionFilter,
                        local!positionFilter,
                        local!subPositionFilter,
                        local!yearFilter,
                        local!nameFilter,
                        local!originatingBuFilter,
                        local!documentId
                      },
                      null
                    ),
                    a!save(local!exportType, null)
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_radioButtonField"(
              choiceLabels: {
                "Nomination Report",
                "Nomination Status Report"
              },
              choiceValues: { 1, 2 },
              value: local!exportType,
              saveInto: {
                local!exportType,
                a!save(local!documentId, null),

              },
              choiceLayout: "COMPACT"
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(icon: "file-excel-o"),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "  Generate Excel Export",
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                )
              },
              link: if(
                or(
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!nominationData, "data", {})),
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!exportType)
                ),
                null,
                #"SYSTEM_SYSRULES_dynamicLink"(
                  saveInto: #"SYSTEM_SYSRULES_startProcess"(
                    processModel: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5163467",
                    processParameters: {
                      regionFilter: local!regionFilter,
                      statusFilter: local!statusFilter,
                      nameFilter: local!nameFilter,
                      nominationTypeFilter: local!typeFilter,
                      originatingBuFilter: local!originatingBuFilter,
                      positionFilter: local!positionFilter,
                      subPositionFilter: local!subPositionFilter,
                      yearFilter: local!yearFilter,
                      exportType: if(
                        local!exportType = 1,
                        #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602124",
                        if(
                          local!exportType = 2,
                          #"_a-0000e781-2d54-8000-9c18-011c48011c48_5419915",
                          null
                        )
                      )
                    },
                    onSuccess: {
                      a!save(
                        local!documentId,
                        fv!processInfo.pv.NewDocument
                      ),
                      a!save(local!isError, false)
                    },
                    onError: {
                      a!save(local!isError, true),
                      a!save(local!documentId, null)
                    }
                  )
                )
              ),
              style: if(
                or(
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!nominationData, "data", {})),
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!exportType)
                ),
                "STANDARD",
                "#00A36C"
              ),
              shape: "SEMI_ROUNDED",
              marginBelow: "STANDARD"
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "download",
                      linkStyle: "STANDALONE",
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: " Download Excel Export",
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                )
              },
              link: #"SYSTEM_SYSRULES_documentDownloadLink"(document: local!documentId),
              style: "#0BDA51",
              shape: "SEMI_ROUNDED",
              marginBelow: "STANDARD"
            )
          },
          showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "refresh",
                      linkStyle: "STANDALONE",
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: " Reset",
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                )
              },
              link: #"SYSTEM_SYSRULES_dynamicLink"(saveInto: a!save(local!documentId, null)),
              style: "STANDARD",
              shape: "SEMI_ROUNDED",
              marginBelow: "STANDARD"
            )
          },
          showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: "There was an error exporting Project Idea Details. Please clear filters and try again.",
            color: "NEGATIVE",
            style: "STRONG"
          ),
          align: "CENTER"
        )
      },
      showWhen: local!isError,
      style: "ERROR",
      marginBelow: "STANDARD"
    ),
    #"SYSTEM_SYSRULES_boxLayout"(
      label: "Nominations",
      isCollapsible: true,
      contents: #"SYSTEM_SYSRULES_gridField_v1"(
        emptyGridMessage: "No Nomination Records Found",
        data: local!nominationData,
        columns: {
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Name",
            sortField: "firstName",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: if(
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(
                    property(fv!row, "fullName", tostring(null))
                  ),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
                  property(fv!row, "fullName", tostring(null))
                ),
                link: #"SYSTEM_SYSRULES_recordLink"(
                  recordType: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3876040",
                  identifier: fv!row.nominationId
                ),
                linkStyle: "STANDALONE",
                color: "ACCENT",
                style: "STRONG"
              )
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Type",
            sortField: "nominationType",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(fv!row, "nominationType", tostring(null))
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Position",
            sortField: "positionType",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(fv!row, "positionType", tostring(null))
            ),
            align: "CENTER"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Sub-Position",
            sortField: "subPosition",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(fv!row, "subPosition", tostring(null))
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Direct Hire",
            sortField: "isDirectHire",
            value: if(
              property(fv!row, "isDirectHire", toboolean(null)),
              #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934655",
              #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934661"
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Level",
            sortField: "levelName",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(fv!row, "levelName", tostring(null))
            )
          ),
          /*a!gridColumn(*/
          /*label: "Originating Region",*/
          /*sortField: "originatingRegion",*/
          /*value: rule!CAW_displayReadOnlyField(*/
          /*value: property(*/
          /*fv!row,*/
          /*"originatingRegion",*/
          /*tostring(null)*/
          /*)*/
          /*)*/
          /*),*/
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Originating BU",
            sortField: "originatingBU",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(fv!row, "originatingBU", tostring(null))
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Originating Office",
            sortField: "originatingHomeOffice",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: property(
                fv!row,
                "originatingHomeOffice",
                tostring(null)
              )
            )
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Status",
            sortField: "nominationStatus",
            value: #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                  value: property(
                    fv!row,
                    "nominationStatus",
                    tostring(null)
                  )
                )
              )
            ),
            width: "NARROW_PLUS"
          )
        },
        pagingSaveInto: local!paging,
        borderStyle: "STANDARD",
        rowHeader: 1
      ),
      style: "ACCENT",
      marginBelow: "STANDARD"
    ),

  }
)
